mapper.select:
select pr.pr_id, pr.display_number, CONCAT_WS(' ', u.last_name, u.first_name) as requester, pr.due_date, pr.total_amount_excluding_tax, pr.status from purchase_request pr join users u on pr.requester_user_id = u.user_id
pr.requester_user_id = #{userId}
and pr.due_date >= #{form.dueDateFrom}
and pr.due_date <= #{form.dueDateTo}
and pr.status = #{form.status}
and ( pr.display_number::varchar ~ #{form.keywordRegex} or normalization(lower(concat(u.last_name, u.first_name))) ~#{form.keywordRegex} or normalization(lower(concat(u.last_name_kana, u.first_name_kana))) ~#{form.keywordRegex} )
order by
pr.display_number concat(u.last_name_kana, u.first_name_kana) pr.due_date
asc nulls first desc nulls last
pr.total_amount_excluding_tax
case pr.status when 'PENDING' then 1 when 'APPROVED' then 2 when 'REJECTED' then 3 when 'COMPLETED' then 4 end
asc desc
limit #{form.size} offset #{form.offset}

select count(*)
from purchase_request pr
join users u
  on pr.requester_user_id = u.user_id


    pr.requester_user_id = #{userId}



    and pr.due_date >= #{form.dueDateFrom}


    and pr.due_date <= #{form.dueDateTo}


    and pr.status = #{form.status}



    and ( 
      pr.display_number::varchar ~ #{form.keywordRegex}
      or normalization(lower(concat(u.last_name, u.first_name))) ~#{form.keywordRegex}
      or normalization(lower(concat(u.last_name_kana, u.first_name_kana))) ~#{form.keywordRegex}
    )
